// ── ¿Toca asignar? ────────────────────────────────────────────────────────
// Guard idempotente SIN banderas: se basa en el estado real del lead.
//   tiene sucursal  Y  NO tiene asesor  →  es el primer contacto ya ubicado.
// Esa combinación sólo ocurre una vez en la vida del lead, así que este sub
// puede correr en cada turno sin riesgo de reasignar.
function F(r){ return (r && r.fields && typeof r.fields === 'object') ? r.fields : (r || {}); }

const trig = $('When Executed by Another Workflow').first().json;
const uid  = String(trig.user_id_canal || '').trim();
const out  = (extra) => [{ json: Object.assign({ asignar:false, user_id_canal:uid }, extra) }];

if (!uid) return out({ motivo:'sin_user_id_canal' });

let rec = null;
try { rec = $('Airtable · Get Lead').all().map(i=>i.json).filter(r=>r && r.id)[0] || null; } catch(e) {}
if (!rec) return out({ motivo:'lead_no_encontrado' });
const L = F(rec);

const sucRec = Array.isArray(L.sucursal_interes) ? L.sucursal_interes[0] : null;
if (!sucRec) return out({ motivo:'sin_sucursal_todavia' });

const yaTiene = Array.isArray(L.asesor_asignado) ? L.asesor_asignado[0] : null;
if (yaTiene) return out({ motivo:'ya_tiene_asesor', asesor_rec: yaTiene });

// Código de sucursal: sale del lookup sucursal_asignada del maestro.
const cod = Array.isArray(L.sucursal_asignada) ? String(L.sucursal_asignada[0] || '') : String(L.sucursal_asignada || '');

return [{ json: {
  asignar: true,
  user_id_canal: uid,
  conversation_id: trig.conversation_id || L.conversation_id || '',
  lead_rec_id: rec.id,
  sucursal_rec: sucRec,
  sucursal_id: cod,
  lead_nombre: L.nombre || 'Cliente',
  lead_ciudad: L.ciudad || '',
  lead_modelo: L.modelo_interes || '',
  lead_score: (L.lead_score != null ? L.lead_score : 0),
  lead_etapa: L.etapa_pipeline || '',
  lead_uso: L.uso_principal || '',
  lead_pago: L.forma_pago_preferida || '',
  lead_summary: L.lead_summary || '',
} }];

// ── Elegir asesor (misma mecánica que el Handoff) ─────────────────────────
function F(r){ return (r && r.fields && typeof r.fields==='object') ? r.fields : (r||{}); }
const G = $('Code · ¿Toca Asignar?').first().json;

// ── FIX: Redis INCR devuelve { "rr:asesor:handoff:CAMP": N }, no { rr_counter: N }
let counter = 1;
try {
  const rr = $('Redis · RR Counter').first().json;
  const vals = Object.values(rr).filter(v => !isNaN(Number(v)));
  if (vals.length) counter = Number(vals[0]) || 1;
} catch(e) {}

let sucNombre = '', sucDir = '';
try { const s = F($('Airtable · Get Sucursal').first().json); sucNombre = s.nombre || ''; sucDir = s.direccion || ''; } catch(e) {}

let candidatos = [];
try {
  candidatos = $('Airtable · Get Asesores').all().map(i=>i.json).filter(r=>r && r.id)
    .map(r => ({ id: r.id, ...F(r) }));
} catch(e) {}

// El filtro por sucursal va en JS, NO en filterByFormula: ARRAYJOIN() de un
// campo link devuelve el primary ("CAMP"), no el recId, y FIND("CAMP","CAMP2")
// haría match cruzado entre las dos de Campeche.
let pool = candidatos.filter(a => Array.isArray(a.sucursal) && a.sucursal.includes(G.sucursal_rec));
let via = pool.length ? 'sucursal' : '';

if (!pool.length) {
  pool = candidatos.filter(a => String(a.asesor_id||'').trim().toUpperCase() === 'CAP-LN');
  if (pool.length) via = 'fallback_capacitacion';
}
if (!pool.length) return [{ json: { ok:false, motivo:'sin_asesores', sucursal_id:G.sucursal_id } }];

// --- Cupo: max_leads_simultaneos ---
// Cuenta leads con bot_paused=true (ya en manos de un humano). Los leads
// pre-asignados por este sub NO están pausados, así que no consumen cupo:
// el asesor los ve en su bandeja pero su capacidad real no se toca.
const carga = {};
try {
  $('Airtable · Carga Actual').all().map(i=>i.json).filter(r=>r && r.id).forEach(r => {
    const f = F(r);
    (Array.isArray(f.asesor_asignado) ? f.asesor_asignado : []).forEach(id => { carga[id] = (carga[id]||0) + 1; });
  });
} catch(e) {}

const conCupo = pool.filter(a => {
  const max = Number(a.max_leads_simultaneos);
  if (!max || max <= 0) return true;
  return (carga[a.id] || 0) < max;
});
if (conCupo.length) pool = conCupo;
else via = via + '+sobre_cupo';

// Orden estable: sin esto el reparto depende del orden que devuelva Airtable.
pool.sort((a,b) => String(a.asesor_id||'').localeCompare(String(b.asesor_id||'')));
const asesor = pool[(counter - 1) % pool.length];

const slackId = String(asesor.slack_id || '').trim();
const tieneSlack = !!slackId && !slackId.startsWith('REEMPLAZA');

// --- Perfil para el aviso (solo lo que tenga valor) ---
const rows = [];
const push = (k,v) => { if (v != null && String(v).trim() !== '') rows.push(`*${k}:* ${v}`); };
push('Ciudad', G.lead_ciudad);
push('Modelo de interés', G.lead_modelo);
push('Uso', G.lead_uso);
push('Forma de pago', G.lead_pago);
push('Etapa', G.lead_etapa);
push('Score', G.lead_score);
const perfil = rows.length ? rows.join('\n') : '_Apenas está empezando la conversación._';

return [{ json: {
  ok: true,
  via,
  pool_size: pool.length,
  user_id_canal: G.user_id_canal,
  conversation_id: G.conversation_id,
  telefono_wa: String(G.user_id_canal||'').replace(/[^0-9]/g,''),
  asesor_rec: asesor.id,
  asesor_id: String(asesor.asesor_id || ''),
  asesor_nombre: asesor.nombre || 'Asesor',
  asesor_slack_id: slackId,
  tiene_slack: tieneSlack,
  chatwoot_agent_id: (asesor.chatwoot_agent_id != null ? asesor.chatwoot_agent_id : null),
  tiene_chatwoot: (asesor.chatwoot_agent_id != null && asesor.chatwoot_agent_id !== ''),
  sucursal_id: G.sucursal_id,
  sucursal_nombre: sucNombre || G.sucursal_id,
  sucursal_direccion: sucDir,
  lead_nombre: G.lead_nombre,
  perfil,
} }];

