function F(r){ return (r && r.fields && typeof r.fields === 'object') ? r.fields : (r || {}); }

const trig = $('When Executed by Another Workflow').first().json;
const uid  = String(trig.user_id_canal || '').trim();
const out  = (extra) => [{ json: Object.assign({ asignar:false, user_id_canal:uid }, extra) }];

if (!uid) return out({ motivo:'sin_user_id_canal' });

let rec = null;
try { rec = $('Airtable · Get Lead1').all().map(i=>i.json).filter(r=>r && r.id)[0] || null; } catch(e) {}
if (!rec) return out({ motivo:'lead_no_encontrado' });
const L = F(rec);

const sucRec = Array.isArray(L.sucursal_interes) ? L.sucursal_interes[0] : null;
if (!sucRec) return out({ motivo:'sin_sucursal_todavia' });

const yaTiene = Array.isArray(L.asesor_asignado) ? L.asesor_asignado[0] : null;
if (yaTiene) return out({ motivo:'ya_tiene_asesor', asesor_rec: yaTiene });

// Código de sucursal: sale del lookup sucursal_asignada del maestro.
const cod = Array.isArray(L.sucursal_asignada) ? String(L.sucursal_asignada[0] || '') : String(L.sucursal_asignada || '');

return [{ json: {
  asignar: true,
  user_id_canal: uid,
  conversation_id: trig.conversation_id || L.conversation_id || '',
  lead_rec_id: rec.id,
  sucursal_rec: sucRec,
  sucursal_id: cod,
  lead_nombre: L.nombre || 'Cliente',
  lead_ciudad: L.ciudad || '',
  lead_modelo: L.modelo_interes || '',
  lead_score: (L.lead_score != null ? L.lead_score : 0),
  lead_etapa: L.etapa_pipeline || '',
  lead_uso: L.uso_principal || '',
  lead_pago: L.forma_pago_preferida || '',
  lead_summary: L.lead_summary || '',
} }];

// ═══════════════════════════════════════════════════════════════════════
// Pick Asesor (Weighted Random con Overflow para multi-sucursal)
// Lee del cache Redis y aplica algoritmo weighted random.
// ═══════════════════════════════════════════════════════════════════════

const G = $('Code · ¿Toca Asignar?1').first().json;

// ── Leer cache de Redis ──
let cache = null;
try {
  const rr = $('Redis · Get Asesores Cache').first().json;
  const raw = rr.asesores_cache || rr.value || Object.values(rr).find(v => typeof v === 'string');
  if (raw) cache = JSON.parse(raw);
} catch(e) {}

if (!cache || !cache.por_sucursal) {
  return [{ json: { 
    ok: false, 
    motivo: 'cache_no_disponible',
    sucursal_id: G.sucursal_id,
    mensaje: 'Cache Redis vacío. Ejecuta manualmente el workflow SYNC · Asesores → Redis.'
  }}];
}

const sucKey = G.sucursal_id;
const sucData = cache.por_sucursal[sucKey];

if (!sucData) {
  return [{ json: { 
    ok: false, 
    motivo: 'sucursal_no_encontrada_en_cache',
    sucursal_id: sucKey 
  }}];
}

// ── Filtrar solo disponibles ──
const primariosDisp = (sucData.primarios || []).filter(a => a.disponible !== false);
const multiDisp = (sucData.multi_sucursal || []).filter(a => a.disponible !== false);

// ── Calcular overflow real (por si algún primario está desactivado) ──
const sumaPrimariosDisp = primariosDisp.reduce((s, a) => s + (Number(a.porcentaje) || 0), 0);
const overflowTotal = Math.max(0, 100 - sumaPrimariosDisp);
const overflowPorMulti = multiDisp.length > 0 ? overflowTotal / multiDisp.length : 0;

// ── Construir lista final de candidatos con % efectivo ──
const candidatos = [];

primariosDisp.forEach(a => {
  const pct = Number(a.porcentaje) || 0;
  if (pct > 0) {
    candidatos.push({ ...a, pct_efectivo: pct, tipo: 'primario' });
  }
});

multiDisp.forEach(a => {
  if (overflowPorMulti > 0) {
    candidatos.push({ ...a, pct_efectivo: overflowPorMulti, tipo: 'multi_overflow' });
  }
});

// ── Fallback: si nadie tiene %, solo hay multi disponible ──
if (candidatos.length === 0 && multiDisp.length > 0) {
  const pctIgual = 100 / multiDisp.length;
  multiDisp.forEach(a => {
    candidatos.push({ ...a, pct_efectivo: pctIgual, tipo: 'multi_fallback' });
  });
}

// ── Sin nadie: alerta ──
if (candidatos.length === 0) {
  return [{ json: { 
    ok: false, 
    motivo: 'sin_asesores_disponibles', 
    sucursal_id: sucKey,
    sucursal_nombre: sucData.sucursal_nombre,
    total_primarios_config: (sucData.primarios || []).length,
    total_multi_config: (sucData.multi_sucursal || []).length
  }}];
}

// ── Weighted random ──
const totalPct = candidatos.reduce((s, a) => s + a.pct_efectivo, 0);
const rand = Math.random() * totalPct;
let acum = 0;
let elegido = candidatos[candidatos.length - 1]; // fallback

for (const c of candidatos) {
  acum += c.pct_efectivo;
  if (rand < acum) {
    elegido = c;
    break;
  }
}

// ── Perfil para el aviso (solo lo que tenga valor) ──
const rows = [];
const push = (k, v) => { if (v != null && String(v).trim() !== '') rows.push(`*${k}:* ${v}`); };
push('Ciudad', G.lead_ciudad);
push('Modelo de interés', G.lead_modelo);
push('Uso', G.lead_uso);
push('Forma de pago', G.lead_pago);
push('Etapa', G.lead_etapa);
push('Score', G.lead_score);
const perfil = rows.length ? rows.join('\n') : '_Apenas está empezando la conversación._';

const slackId = String(elegido.slack_id || '').trim();
const tieneSlack = !!slackId && !slackId.startsWith('REEMPLAZA');

return [{ json: {
  ok: true,
  via: elegido.tipo,
  pool_size: candidatos.length,
  pct_efectivo_ganador: Math.round(elegido.pct_efectivo * 100) / 100,
  suma_pct_total: Math.round(totalPct * 100) / 100,
  user_id_canal: G.user_id_canal,
  conversation_id: G.conversation_id,
  telefono_wa: String(G.user_id_canal || '').replace(/[^0-9]/g, ''),
  asesor_rec: elegido.asesor_rec,
  asesor_id: String(elegido.asesor_id || ''),
  asesor_nombre: elegido.nombre || 'Asesor',
  asesor_slack_id: slackId,
  tiene_slack: tieneSlack,
  chatwoot_agent_id: elegido.chatwoot_agent_id,
  tiene_chatwoot: (elegido.chatwoot_agent_id != null && elegido.chatwoot_agent_id !== ''),
  sucursal_id: G.sucursal_id,
  sucursal_nombre: sucData.sucursal_nombre || G.sucursal_id,
  sucursal_direccion: sucData.sucursal_direccion || '',
  lead_nombre: G.lead_nombre,
  perfil,
}}];

